 * @return bool
 */
public function replicaShouldKeepRelation($relation)
{
    $this->workbench['replication']['pivot'] = $relation instanceof Pivot;

    if ($this->workbench['replication']['pivot']) {
        return false;
    }

    if (is_object($relation) && in_array(AsPivot::class, class_uses_recursive($relation), true)) {
        $this->workbench['replication']['as_pivot'] = true;

        return false;
    }

    return true;
}

